"use client";

import React, { useMemo, useRef } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { Float, Sparkles } from "@react-three/drei";
import * as THREE from "three";

interface HeroSceneProps {
  accent: string;
  accentSecondary: string;
  reducedMotion: boolean;
}

function CryoCore({ accent, accentSecondary, reducedMotion }: HeroSceneProps) {
  const outerRef = useRef<THREE.Mesh>(null);
  const innerRef = useRef<THREE.Mesh>(null);
  const ring1Ref = useRef<THREE.Mesh>(null);
  const ring2Ref = useRef<THREE.Mesh>(null);
  const groupRef = useRef<THREE.Group>(null);

  useFrame((state, delta) => {
    const dt = Math.min(delta, 0.05);
    const speed = reducedMotion ? 0.15 : 1;

    if (outerRef.current) {
      outerRef.current.rotation.y += dt * 0.25 * speed;
      outerRef.current.rotation.x += dt * 0.12 * speed;
    }
    if (innerRef.current) {
      innerRef.current.rotation.y -= dt * 0.4 * speed;
      innerRef.current.rotation.z += dt * 0.18 * speed;
    }
    if (ring1Ref.current) {
      ring1Ref.current.rotation.z += dt * 0.32 * speed;
    }
    if (ring2Ref.current) {
      ring2Ref.current.rotation.z -= dt * 0.24 * speed;
    }
    if (groupRef.current && !reducedMotion) {
      const targetX = state.pointer.y * 0.22;
      const targetY = state.pointer.x * 0.28;
      groupRef.current.rotation.x = THREE.MathUtils.lerp(groupRef.current.rotation.x, targetX, 0.05);
      groupRef.current.rotation.y = THREE.MathUtils.lerp(groupRef.current.rotation.y, targetY, 0.05);
    }
  });

  const ringPoints = useMemo(() => {
    const pts: THREE.Vector3[] = [];
    for (let i = 0; i <= 64; i++) {
      const a = (i / 64) * Math.PI * 2;
      pts.push(new THREE.Vector3(Math.cos(a) * 2.45, Math.sin(a) * 2.45, 0));
    }
    return pts;
  }, []);

  void ringPoints;

  return (
    <group ref={groupRef} position={[0, 0, 0]}>
      <Float speed={reducedMotion ? 0.5 : 1.8} rotationIntensity={0.3} floatIntensity={0.55}>
        {/* Outer crystalline wireframe */}
        <mesh ref={outerRef}>
          <icosahedronGeometry args={[1.55, 1]} />
          <meshStandardMaterial
            color={accent}
            wireframe
            transparent
            opacity={0.55}
            emissive={accent}
            emissiveIntensity={0.65}
          />
        </mesh>

        {/* Inner faceted crystal core */}
        <mesh ref={innerRef} scale={0.92}>
          <octahedronGeometry args={[1.05, 0]} />
          <meshPhysicalMaterial
            color={accentSecondary}
            roughness={0.18}
            metalness={0.75}
            clearcoat={1}
            clearcoatRoughness={0.1}
            emissive={accentSecondary}
            emissiveIntensity={0.35}
          />
        </mesh>
      </Float>

      {/* Orbital algorithmic rings */}
      <mesh ref={ring1Ref} rotation={[Math.PI / 2.6, 0.3, 0]}>
        <torusGeometry args={[2.35, 0.015, 16, 120]} />
        <meshBasicMaterial color={accent} transparent opacity={0.45} />
      </mesh>
      <mesh ref={ring2Ref} rotation={[-Math.PI / 3.1, -0.45, 0]}>
        <torusGeometry args={[2.85, 0.012, 16, 120]} />
        <meshBasicMaterial color={accentSecondary} transparent opacity={0.32} />
      </mesh>

      <Sparkles
        count={reducedMotion ? 35 : 85}
        scale={7.5}
        size={2.2}
        speed={reducedMotion ? 0.1 : 0.4}
        opacity={0.65}
        color={accent}
      />
    </group>
  );
}

export default function HeroCanvas({
  accent,
  accentSecondary,
  reducedMotion,
}: HeroSceneProps) {
  return (
    <div className="relative h-full w-full select-none">
      <Canvas
        camera={{ position: [0, 0, 6.2], fov: 44 }}
        dpr={[1, 2]}
        gl={{ antialias: true, alpha: true, powerPreference: "high-performance" }}
      >
        <ambientLight intensity={0.7} />
        <pointLight position={[5, 5, 5]} intensity={2.2} color={accent} />
        <pointLight position={[-5, -4, 3]} intensity={1.6} color={accentSecondary} />
        <CryoCore
          accent={accent}
          accentSecondary={accentSecondary}
          reducedMotion={reducedMotion}
        />
      </Canvas>
    </div>
  );
}
